CREATE COLUMN TABLE "TEST_AP"."UGP1" ("UgpEntry" INTEGER CS_INT NOT NULL , "UomEntry" INTEGER CS_INT NOT NULL , "AltQty" DECIMAL(21,6) CS_FIXED, "BaseQty" DECIMAL(21,6) CS_FIXED, "LogInstanc" INTEGER CS_INT DEFAULT 0, "LineNum" INTEGER CS_INT NOT NULL , "WghtFactor" SMALLINT CS_INT DEFAULT 0, "UdfFactor" INTEGER CS_INT DEFAULT -1, "IsActive" NVARCHAR(1) DEFAULT 'Y', PRIMARY KEY ("UgpEntry", "LineNum")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "UGP1_GROUP" ON "TEST_AP"."UGP1" ( "UgpEntry" ASC, "UomEntry" ASC )